const wines = [
 {id:76,name:'Pago de Carraovejas',region:'Ribera del Duero',edition:'2018 · etiqueta representada',position:'35% center',source:'https://www.pagodecarraovejas.com/wp-content/uploads/2021/11/20210315_PDC18_FichaCata_WEB_ENG.pdf',description:'Pago de Carraovejas 2018 reúne tinto fino, cabernet sauvignon y merlot en un Ribera del Duero de volumen generoso y pulso fresco. La fruta se acompaña de matices florales; la estructura sostiene una sensación envolvente, dinámica y elegante. Nuestra sugerencia: descubrirlo con el solomillo de retinta, dejando que la copa revele lentamente su profundidad y el carácter de su origen.'},
 {id:77,name:'Valbuena 5º',region:'Vega Sicilia · Ribera del Duero',edition:'Añada a consultar',position:'center',source:'https://www.temposvegasicilia.com/es/vino/236/valbuena-5/1990',description:'Valbuena 5º expresa el tinto fino de Vega Sicilia, acompañado de merlot según la cosecha. Sus cinco años entre madera y botella construyen una identidad donde importan el tiempo, el origen y la textura. Un Ribera del Duero para descubrir despacio. Nuestra sugerencia: acompañarlo con carne a la parrilla y consultar la añada para apreciar sus matices con mayor precisión.'},
 {id:78,name:'Marqués de Riscal Reserva',region:'Rioja',edition:'Añada a consultar',position:'center',source:'https://www.marquesderiscal.com/marques-de-riscal-reserva',description:'Marqués de Riscal Reserva representa una manera clásica de entender Rioja, con tempranillo y graciano y una vocación claramente gastronómica. Su versatilidad permite recorrer la mesa desde el jamón hasta los asados, sin exigir un único protagonista. Nuestra sugerencia: disfrutarlo con ibéricos o carnes a la parrilla, servido entre dieciséis y dieciocho grados para acompañar la conversación con calma elegante.'},
 {id:79,name:'Matarromera Crianza',region:'Ribera del Duero',edition:'Añada a consultar',position:'60% center',source:'https://tienda.matarromera.es/es/do-ribera-del-duero/1349-55-matarromera-crianza.html',description:'Matarromera Crianza muestra la intensidad del tempranillo de Ribera del Duero: fruta negra madura, regaliz y recuerdos de café y vainilla, acompañados por roble francés y americano. En boca resulta amplio, estructurado y generoso, con taninos maduros y un final de carácter frutal y especiado. Nuestra sugerencia: servirlo con jamón ibérico, quesos o el solomillo de retinta de nuestra carta.'},
 {id:80,name:'Habla del Silencio',region:'Bodegas HABLA · Extremadura',edition:'Añada a consultar',position:'center',source:'https://www.bodegashabla.com/producto/habla-del-silencio/',description:'Habla del Silencio une syrah, cabernet sauvignon y tempranillo en un tinto extremeño de expresión frutal y especiada. Cereza, grosella, pimienta y recuerdos de moca dibujan un perfil goloso, fresco y carnoso. La madera francesa acompaña su intensidad sin borrar la fruta. Nuestra sugerencia: compartirlo con la carrillada ibérica y dejar que su carácter se abra despacio en la copa.'}
];
const iconPaths={arrow:'M4 12h15m-6-6 6 6-6 6',back:'M20 12H5m6-6-6 6 6 6',diagonal:'M5 19 19 5M5 5h14v14',close:'m6 6 12 12M18 6 6 18'};
function plazaIcon(kind='arrow') {return `<svg class="plaza-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false"><path d="${iconPaths[kind]}" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
// Replace typographic arrows and close marks, including dynamically rendered menus.
function vectorize(root){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){if(node.parentElement.closest('script,style,svg'))continue;const parts=node.textContent.split(/([↗→←×])/u);if(parts.length===1)continue;const fragment=document.createDocumentFragment();for(const part of parts){if('↗→←×'.includes(part)&&part){const holder=document.createElement('template');holder.innerHTML=plazaIcon({'↗':'diagonal','→':'arrow','←':'back','×':'close'}[part]);fragment.append(holder.content);}else fragment.append(document.createTextNode(part));}node.replaceWith(fragment);}
}
const wineDialog=document.createElement('dialog');wineDialog.className='wine-dialog';wineDialog.setAttribute('aria-labelledby','wine-title');wineDialog.setAttribute('aria-describedby','wine-description');
wineDialog.innerHTML=`<button class="dialog-close" aria-label="Cerrar ficha del vino">${plazaIcon('close')}</button><div class="wine-portrait"><img width="3840" height="2160" alt=""></div><div class="wine-copy"><p class="eyebrow wine-region"></p><h2 id="wine-title"></h2><span class="wine-edition"></span><p id="wine-description"></p><a class="text-link wine-source" target="_blank" rel="noopener">Conocer la bodega ${plazaIcon('diagonal')}</a><p class="wine-note">Imagen recreada con IA. Consulta la añada y disponibilidad en el restaurante.</p><div class="wine-pagination"><button data-wine-prev aria-label="Vino anterior">${plazaIcon('back')}</button><span></span><button data-wine-next aria-label="Vino siguiente">${plazaIcon()}</button></div></div>`;
document.body.append(wineDialog);let activeWine=0,wineTrigger=null;
function openWine(id){const index=wines.findIndex(w=>w.id===Number(id));if(index<0)return;activeWine=index;const wine=wines[index];const photo=wineDialog.querySelector('img');photo.style.opacity='0';photo.onload=()=>photo.style.opacity='1';photo.src=`assets/4k/venue-${wine.id}.webp`;photo.alt=wine.name+', recreación con IA';photo.style.objectPosition=wine.position;wineDialog.querySelector('.wine-region').textContent=wine.region;wineDialog.querySelector('h2').textContent=wine.name;wineDialog.querySelector('.wine-edition').textContent=wine.edition;wineDialog.querySelector('#wine-description').textContent=wine.description;wineDialog.querySelector('.wine-source').href=wine.source;wineDialog.querySelector('.wine-pagination span').textContent=`0${index+1} / 05`;if(!wineDialog.open){wineTrigger=document.activeElement;wineDialog.showModal();document.body.style.overflow='hidden';}}
wineDialog.querySelector('.dialog-close').onclick=()=>wineDialog.close();wineDialog.addEventListener('close',()=>{document.body.style.overflow='';wineTrigger?.focus();});
wineDialog.querySelector('[data-wine-prev]').onclick=()=>openWine(wines[(activeWine+4)%5].id);wineDialog.querySelector('[data-wine-next]').onclick=()=>openWine(wines[(activeWine+1)%5].id);
wineDialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();openWine(wines[(activeWine+(e.key==='ArrowLeft'?4:1))%5].id);}});
document.querySelectorAll('.wine-rail figure').forEach((figure,index)=>{const wine=wines[index];const button=document.createElement('button');button.className='wine-select';button.dataset.wine=wine.id;button.setAttribute('aria-label','Descubrir '+wine.name);button.setAttribute('aria-haspopup','dialog');const photo=figure.querySelector('img');button.append(photo);const prompt=document.createElement('span');prompt.className='wine-discover';prompt.innerHTML=`Descubrir el vino ${plazaIcon()}`;button.append(prompt);figure.prepend(button);figure.querySelector('figcaption').innerHTML=`<span>0${index+1} / ${wine.region}</span>${wine.name}`;button.onclick=()=>openWine(wine.id);});
// The same photograph opens the same bottle in the extended gallery and menu.
document.addEventListener('click',event=>{const trigger=event.target.closest('.collection-item,.dish-select');if(!trigger)return;const photo=trigger.querySelector('img');const match=photo?.getAttribute('src')?.match(/venue-(7[6-9]|80)\.webp/);if(match){event.preventDefault();event.stopImmediatePropagation();openWine(match[1]);}},true);
document.querySelectorAll('.button').forEach(button=>{if(!/[↗→←×]/u.test(button.textContent))button.insertAdjacentHTML('beforeend',plazaIcon());});
vectorize(document.body);new MutationObserver(records=>{for(const record of records){for(const node of record.addedNodes){if(node.nodeType===1&&!node.matches('svg,.plaza-icon'))vectorize(node);else if(node.nodeType===3&&/[↗→←×]/u.test(node.textContent))vectorize(node.parentElement);}}}).observe(document.body,{childList:true,subtree:true});
